INSERT INTO equipment_catalog_items (
    slot,
    name,
    level_requirement,
    progression_stage,
    set_name,
    job_group,
    name_pattern,
    base_stats,
    star_force_profile,
    notes
)
SELECT
    slot::varchar,
    name,
    level_requirement,
    progression_stage,
    set_name,
    job_group,
    name_pattern,
    base_stats::jsonb,
    star_force_profile,
    notes
FROM sheet_catalog
ON CONFLICT (slot, name) DO UPDATE SET
    level_requirement = COALESCE(EXCLUDED.level_requirement, equipment_catalog_items.level_requirement),
    progression_stage = COALESCE(EXCLUDED.progression_stage, equipment_catalog_items.progression_stage),
    set_name = COALESCE(EXCLUDED.set_name, equipment_catalog_items.set_name),
    job_group = COALESCE(EXCLUDED.job_group, equipment_catalog_items.job_group),
    name_pattern = EXCLUDED.name_pattern,
    base_stats = COALESCE(EXCLUDED.base_stats, equipment_catalog_items.base_stats),
    star_force_profile = COALESCE(EXCLUDED.star_force_profile, equipment_catalog_items.star_force_profile),
    notes = COALESCE(EXCLUDED.notes, equipment_catalog_items.notes);
